import { VeryfrontError } from "../../errors/index.js";
import { formatSchemaValidationErrors, OutputSchemaValidationError, toSchemaValidationErrors, } from "../../schemas/validation-errors.js";
/** Whether an execution failure carries structured run-error metadata. */
export function isWorkflowExecutionError(error) {
    return error instanceof VeryfrontError || error instanceof OutputSchemaValidationError;
}
/** Parse one workflow output or raise the typed validation failure persisted on its run. */
export function parseWorkflowOutput(workflow, output) {
    if (!workflow.outputSchema)
        return output;
    const result = workflow.outputSchema.safeParse(output);
    if (result.success)
        return result.data;
    const errors = toSchemaValidationErrors(result.issues ?? []);
    throw new OutputSchemaValidationError(`Workflow "${workflow.id}" output failed outputSchema validation: ${formatSchemaValidationErrors(errors)}`, errors);
}
